const navigationChapters=chapters.filter(c=>c.page>=4);
function chapterRange(index){if(index<=2)return {start:0,end:2,title:'Bagian awal',number:''};let selected=0;for(let k=0;k<navigationChapters.length;k++){if(navigationChapters[k].page-1<=index)selected=k;}const chapter=navigationChapters[selected];return {start:chapter.page-1,end:navigationChapters[selected+1]?navigationChapters[selected+1].page-2:pages.length-1,title:chapter.menuTitle||chapter.title,number:chapter.number||''};}
