function footer(i){return `<div class="folio"><nav class="page-nav" aria-label="Navigasi halaman"><button type="button" data-book-action="prev" aria-label="Kembali ke halaman sebelumnya"><span class="nav-symbol" aria-hidden="true">←</span><span>Kembali</span></button><span class="nav-divider"></span><button type="button" data-book-action="menu" aria-label="Kembali ke menu utama"><svg class="nav-home-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 10.7 12 3l9 7.7v9.1a1 1 0 0 1-1 1h-5.3v-6.1H9.3v6.1H4a1 1 0 0 1-1-1z"/></svg><span class="nav-text"><span>Menu</span><span class="nav-hint" aria-hidden="true">bab berikutnya</span></span></button><span class="nav-divider"></span><button type="button" data-book-action="next" aria-label="Lanjut ke halaman berikutnya"><span>Lanjut</span><span class="nav-symbol" aria-hidden="true">→</span></button></nav><span class="page-number">${i}</span></div>`}
