function renderPage(p,i){if(!p)return '';let h=`<span class="page-kicker">${escape(p.label||'Jelajah warisan budaya lokal')}</span>`;
 if(p.kind==='cover')return `<img class="cover-art" src="./assets/cover.png?v=muslim-1" alt="Ilustrasi konseptual anak menjelajahi lanskap Ngawi"><div class="cover-title"><div class="cover-logos"><span class="ngawi-logo"><img src="./assets/logo-ngawi.png" alt="Lambang Kabupaten Ngawi"></span><img class="stkip-logo" src="./assets/logo-stkip.png?v=transparan-1" alt="Logo STKIP Modern Ngawi"></div><span class="tiny">BUKU SAKU DIGITAL · WARBULA</span><h2>Kebudayaan<br>Ngawi</h2><p>Warisan yang dekat dengan kita.</p></div><div class="cover-author"><button type="button" class="cv-go cv-start" data-book-action="start" aria-label="Mulai jelajah: buka menu utama 12 bab" title="Mulai jelajah"><svg viewBox="0 0 24 24" width="36" height="36" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" stroke-width="1.5"/><g class="cv-needle"><path d="M12 4l3.2 8h-6.4z" fill="#fff8e6"/><path d="M12 20l-3.2-8h6.4z" fill="#e2bd6f"/></g><circle cx="12" cy="12" r="1.4" fill="#1d4636"/></svg></button><div class="cv-by"><small>DITULIS OLEH</small><strong>Bagas Junianto</strong></div><button type="button" class="cv-go cv-side" data-book-action="overview" aria-label="Lihat semua halaman"></button></div>`;
 if(p.kind==='back')return `<div class="back-art">${icon('leaf')}<h2>${title(p.title)}</h2><p>${escape(p.text)}</p><div class="divider"></div><p class="small">${escape(p.note)}</p><button class="solid-button" data-page="1">Kembali ke sampul ↑</button></div>`;
 if(p.kind==='intro')return `<div class="page-body intro-page"><span class="page-kicker">${escape(p.label)}</span><h2>${title(p.title)}</h2><div class="welcome-bubble"><span class="bubble-rays" aria-hidden="true"></span><span class="bubble-rays bubble-rays-right" aria-hidden="true"></span><span class="bubble-tail bubble-tail-left" aria-hidden="true"></span><span class="bubble-tail bubble-tail-right" aria-hidden="true"></span><p>${escape(p.text).replace(' di WARBULA!',' di<br>WARBULA!').replace(' mengenal warisan',' mengenal<br>warisan').replace(' budaya lokal Ngawi.',' budaya lokal<br>Ngawi.')}</p></div><img class="intro-mascots" src="${escape(p.image)}" alt="Dua maskot penjelajah menyapa pembaca; anak perempuan memakai hijab dan baju lengan panjang"><p class="intro-note">${escape(p.note)}</p><button class="intro-start" data-page="3">Pilih bab →</button></div>${footer(i)}`;
 if(p.kind==='menu')return `<div class="page-body menu-page"><span class="page-kicker">${escape(p.label)}</span><h2>${title(p.title)}</h2><p class="menu-intro">${escape(p.text)}</p><nav class="chapter-grid" aria-label="Pilih bab">${chapters.filter(c=>c.number).map(c=>`<button class="chapter-tile" data-page="${c.page}" aria-label="${escape(c.menuTitle)}, bab ${c.number}"><span class="tile-number">${c.number}</span><span class="tile-icon"><img src="./assets/menu-icons/bab-${c.number}.png" alt="" width="91" height="43"></span><span class="tile-label">${escape(c.menuTitle)}</span></button>`).join('')}</nav><div class="passport" aria-live="polite"><div class="passport-bar"><i></i></div><div class="passport-row"><span class="passport-text"></span><button type="button" class="passport-next" hidden></button></div></div><div class="menu-extra">${chapters.filter(c=>['Glosarium','Daftar pustaka'].includes(c.title)).map(c=>`<button data-page="${c.page}">${escape(c.title)}</button>`).join('')}<button type="button" data-badges>Lencana ${badgeList().filter(b=>b.ok).length}/${badgeList().length}</button></div></div>${footer(i)}`;
 if(p.kind==='title')return `<div class="page-body title-body"><span class="page-kicker">Selamat datang di WARBULA</span><div class="flourish">❧</div><h2>${title(p.title)}</h2><p class="lead">${escape(p.text)}</p><div class="divider"></div><p class="small">${escape(p.note)}</p></div>${footer(i)}`;
 if(p.kind==='contents')h+=`<h2>${title(p.title)}</h2><div class="toc-page">${chapters.slice(1).map((c,k)=>`<button data-page="${c.page}"><span>${escape(c.number||'·')}</span>${escape(c.title)}<span>${c.page}</span></button>`).join('')}</div>`;
 else if(p.kind==='goals')h+=`<h2>${title(p.title)}</h2><p>${escape(p.text)}</p><ol>${p.items.map(s=>`<li>${escape(s)}</li>`).join('')}</ol><div class="callout"><strong>CARA MEMBACA</strong><p>${escape(p.note)}</p></div>`;
 else if(p.kind==='chapter')h+=`<div class="chapter-top"><div class="chapter-number">${p.number}</div><span class="chapter-icon">${icon(p.icon)}</span></div><h2>${title(p.title)}</h2><div class="chapter-ornament"><span></span><span></span><span></span></div><p class="lead">${escape(p.text)}</p>${p.status?`<span class="status-chip">${p.status}</span>`:''}${p.note?`<p class="small">${escape(p.note)}</p>`:''}`;
 else if(p.kind==='article')h+=`<h2>${title(p.title)}</h2>${p.image?`<figure class="history-photo"><img src="${escape(p.image)}" alt="${escape(p.imageAlt)}" width="1280" height="960"><figcaption>${escape(p.imageCaption)}</figcaption></figure>`:''}<p>${escape(p.text)}</p>${(p.paragraphs||[]).map(s=>`<p>${escape(s)}</p>`).join('')}${p.note?`<div class="callout"><strong>${p.note.includes('?')?'AYO PIKIRKAN':'CATATAN JELAJAH'}</strong><p>${escape(p.note)}</p></div>`:''}`;
 else if(p.kind==='video')h+=`<h2>${title(p.title)}</h2><p>${escape(p.text)}</p><button type="button" class="video-card" data-video="${escape(p.videoId)}"><span aria-hidden="true">▶</span><strong>Buka video pengamatan</strong><small>Memerlukan koneksi internet</small></button><div class="callout"><strong>AYO AMATI</strong><p>${escape(p.note)}</p></div>`;
 else if(p.kind==='quiz')h+=`<h2>${title(p.title)}</h2><div class="quiz-pair">${p.questions.map(q=>`<section class="quiz-card" data-question="${escape(q.id)}"><h3>${escape(q.prompt)}</h3><div class="quiz-options" role="group" aria-label="${escape(q.prompt)}">${q.options.map((opt,n)=>`<button type="button" class="quiz-option" data-choice="${n}" aria-pressed="false"><span>${String.fromCharCode(65+n)}</span>${escape(opt)}</button>`).join('')}</div><button type="button" class="quiz-check" data-check="${escape(q.id)}">Periksa</button><p class="quiz-feedback" role="status" aria-live="polite">Pilih satu jawaban, lalu periksa.</p></section>`).join('')}</div>`;
 else if(p.kind==='quiz-summary')h+=`<h2>${title(p.title)}</h2><p class="quiz-summary-intro">${escape(p.text)}</p><div class="quiz-score" role="status" aria-live="polite"></div><div class="quiz-review"></div><button type="button" class="quiz-reset" data-reset-quiz>Ulangi latihan</button><p class="quiz-privacy">Hasil hanya berlaku selama buku ini terbuka. Memuat ulang halaman akan menghapus jawaban.</p>`;
 else if(p.kind==='glossary')h+=`<h2>${title(p.title)}</h2><dl class="glossary-list">${p.entries.map(e=>`<div><dt>${escape(e.term)}</dt><dd>${escape(e.definition)}</dd></div>`).join('')}</dl>`;
 else if(p.kind==='map')h+=`<h2>${title(p.title)}</h2><figure class="district-map"><img src="${escape(p.image)}" alt="${escape(p.imageAlt)}" width="1181" height="760"><figcaption>${escape(p.caption)}</figcaption><button class="map-enlarge" type="button" data-open-map>⤢ Jelajahi peta</button></figure><div class="region-stats">${p.stats.map(s=>`<div><strong>${escape(s[0])}</strong><span>${escape(s[1])}</span></div>`).join('')}</div><div class="region-area"><span>LUAS WILAYAH</span><strong>${escape(p.area)}</strong></div>${p.population?`<div class="region-population"><div><span>JUMLAH PENDUDUK</span><strong>${escape(p.population)}</strong></div><small>${escape(p.populationPeriod)}</small></div>`:''}`;
 else if(p.kind==='districts')h+=`<h2>${title(p.title)}</h2><ol class="district-list">${p.items.map((s,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span>${escape(s)}</li>`).join('')}</ol>`;
 else if(p.kind==='route')h+=`<h2>${title(p.title)}</h2><div class="map-path">${chapters.slice(3,10).map((c,k)=>`<button class="map-stop" data-page="${c.page}"><em>${k+1}</em><span>${escape(c.title)}<small>Buka halaman ${c.page} ↗</small></span></button>`).join('')}</div><p class="small">${escape(p.note)}</p>`;
 else if(p.kind==='references')h+=`<h2>${title(p.title)}</h2><div class="bibliography">${p.entries.map(e=>`<section><span class="ref-type">${escape(e.type)}</span><h3>${escape(e.title)}</h3><p>${escape(e.text)}</p>${e.url?`<a href="${escape(e.url)}" target="_blank" rel="noopener">${escape(e.linkLabel)} ↗</a>`:''}${e.license?`<a href="${escape(e.license)}" target="_blank" rel="noopener">${escape(e.licenseLabel)} ↗</a>`:''}</section>`).join('')}</div>`;
 else if(p.kind==='closing')h+=`<div class="chapter-icon">${icon('leaf')}</div><h2>${title(p.title)}</h2><p class="lead">${escape(p.text)}</p><p>${escape(p.note)}</p><div class="divider"></div><p class="small">Mengenal, menghargai, melestarikan.</p><button class="solid-button" data-page="1">Kembali ke sampul ↑</button>`;
 else h+=`<h2>${title(p.title)}</h2>${reserved(p)}<p class="question">${escape(p.note)}</p>`;
 return `<div class="page-body${p.kind==='quiz'?' quiz-page':''}">${h}</div>`+footer(i)}

// Learning progress is kept in memory for this reading session only.
const quizQuestions=pages.flatMap((p,index)=>(p.questions||[]).map(q=>({...q,page:index+1}))),quizProgress=new Map();
function updateQuizSummary(){const checked=[...quizProgress.values()].filter(s=>s.checked),correct=checked.filter(s=>s.correct).length;document.querySelectorAll('.quiz-score').forEach(el=>{const total=quizQuestions.length,done=checked.length,finished=done===total,rank=!finished?{t:'Gelar belum terbuka',m:done?`${done} dari ${total} soal diperiksa. Lanjutkan untuk membuka gelarmu.`:'Jawab dan periksa semua soal untuk membuka gelar penjelajah.'}:correct===total?{t:'Pelestari Warisan',m:'Semua jawabanmu benar. Kamu siap menjaga warisan budaya Ngawi!'}:correct>=total*0.75?{t:'Penjelajah Mahir',m:'Hampir sempurna. Baca ulang bagian bertanda ↻ untuk melengkapinya.'}:correct>=total*0.5?{t:'Penjelajah Muda',m:'Sudah separuh jalan. Buka lagi bab yang bertanda ↻, lalu coba kembali.'}:{t:'Mari Jelajah Lagi',m:'Tidak apa-apa. Baca ulang bab bertanda ↻, lalu ulangi latihan.'};
 el.className='quiz-score'+(finished?' finished':'');el.style.setProperty('--pct',(finished?correct/total*100:done/total*100)+'%');el.innerHTML=`<div class="score-ring"><b>${correct}</b><span>benar dari ${total}</span></div><div class="score-text"><strong>${rank.t}</strong><p>${rank.m}</p></div>`});document.querySelectorAll('.quiz-review').forEach(el=>{el.innerHTML=quizQuestions.map((q,i)=>{const state=quizProgress.get(q.id),status=!state?.checked?'Belum diperiksa':state.correct?'Benar':'Baca ulang';return `<div class="${!state?.checked?'is-todo':state.correct?'is-ok':'is-retry'}"><span>${i+1}. ${escape(q.id==='wilayah'?'Wilayah Ngawi':q.id==='trinil'?'Koleksi Trinil':q.id==='benteng'?'Fungsi benteng':q.id==='soerjo'?'Monumen Soerjo':q.id==='radjiman'?'Peran Radjiman':q.id==='penthul'?'Penthul Melikan':q.id==='keduk'?'Sumber air':'Tari Orek-Orek')}</span><button data-page="${state?.checked&&!state.correct?q.readPage:q.page}">${state?.checked?(state.correct?'✓ ':'↻ '):'○ '}${status}</button></div>`}).join('')})}
document.addEventListener('click',e=>{const option=e.target.closest('[data-choice]'),check=e.target.closest('[data-check]');if(option){const card=option.closest('[data-question]'),id=card.dataset.question;quizProgress.set(id,{choice:+option.dataset.choice,checked:false});card.querySelectorAll('.is-correct,.is-wrong').forEach(b=>b.classList.remove('is-correct','is-wrong'));card.querySelectorAll('[data-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===option)));card.querySelector('.quiz-feedback').textContent='Jawaban dipilih. Tekan Periksa.';card.querySelector('.quiz-feedback').removeAttribute('data-result');updateQuizSummary()}if(check){const id=check.dataset.check,q=quizQuestions.find(q=>q.id===id),state=quizProgress.get(id),feedback=check.closest('[data-question]').querySelector('.quiz-feedback');if(!state){feedback.textContent='Pilih jawaban terlebih dahulu.';return}state.checked=true;state.correct=state.choice===q.answer;feedback.dataset.result=state.correct?'correct':'retry';check.closest('[data-question]').querySelectorAll('[data-choice]').forEach(b=>{b.classList.toggle('is-correct',+b.dataset.choice===q.answer);b.classList.toggle('is-wrong',+b.dataset.choice===state.choice&&!state.correct)});feedback.textContent=(state.correct?'Benar. ':'Coba baca ulang. ')+q.explanation;updateQuizSummary()}if(e.target.closest('[data-reset-quiz]')){quizProgress.clear();document.querySelectorAll('.is-correct,.is-wrong').forEach(b=>b.classList.remove('is-correct','is-wrong'));document.querySelectorAll('[data-choice]').forEach(b=>b.setAttribute('aria-pressed','false'));document.querySelectorAll('.quiz-feedback').forEach(el=>{el.textContent='Pilih satu jawaban, lalu periksa.';el.removeAttribute('data-result')});updateQuizSummary()}});

/* Sesi 9: hasil kuis tersimpan + rekor terbaik */
const QK='warbula-quiz',QB='warbula-quiz-best';
function quizBest(){try{const n=Number(localStorage.getItem(QB));return Number.isInteger(n)&&n>0?n:0}catch{return 0}}
function quizMark(){const total=quizQuestions.length,st=[...quizProgress.values()].filter(s=>s.checked),ok=st.filter(s=>s.correct).length;if(st.length===total&&ok>quizBest()){try{localStorage.setItem(QB,String(ok))}catch{}}const best=quizBest();document.querySelectorAll('.quiz-score .score-text').forEach(t=>{t.querySelector('.quiz-share')?.remove();if(st.length===total)t.insertAdjacentHTML('beforeend','<button type="button" class="quiz-share" data-share-card>Bagikan kartu ↗</button>');t.querySelector('.quiz-best')?.remove();if(best)t.insertAdjacentHTML('beforeend',`<small class="quiz-best">★ Rekor terbaikmu: ${best} dari ${total}${best===total?' · sempurna':''}</small>`)})}
function quizSave(){try{localStorage.setItem(QK,JSON.stringify(Object.fromEntries(quizProgress)))}catch{}quizMark()}
setTimeout(()=>{try{const raw=JSON.parse(localStorage.getItem(QK)||'{}');quizQuestions.forEach(q=>{const s=raw[q.id];if(!s||!Number.isInteger(s.choice)||s.choice<0||s.choice>=(q.options||[]).length)return;const card=document.querySelector(`[data-question="${q.id}"]`);quizProgress.set(q.id,{choice:s.choice,checked:!!s.checked,correct:!!s.checked&&s.choice===q.answer});if(!card)return;card.querySelectorAll('[data-choice]').forEach(b=>{const c=+b.dataset.choice;b.setAttribute('aria-pressed',String(c===s.choice));if(s.checked){b.classList.toggle('is-correct',c===q.answer);b.classList.toggle('is-wrong',c===s.choice&&s.choice!==q.answer)}});const f=card.querySelector('.quiz-feedback');if(f&&s.checked){const ok=s.choice===q.answer;f.dataset.result=ok?'correct':'retry';f.textContent=(ok?'Benar. ':'Coba baca ulang. ')+q.explanation}else if(f)f.textContent='Jawaban dipilih. Tekan Periksa.'})}catch{}updateQuizSummary();quizMark()},0);

/* Sesi 10: Kartu Penjelajah */
function cardInfo(){const total=quizQuestions.length,st=[...quizProgress.values()].filter(s=>s.checked),ok=st.filter(s=>s.correct).length,gelar=document.querySelector('.quiz-score strong')?.textContent||'Penjelajah',nb=chapters.filter(c=>c.number).length;return{total,ok,gelar,cap:stamps.size,nb,best:quizBest()}}
