function speechLines(indices){const lines=[];indices.forEach(i=>{const body=book.querySelectorAll('.book-page')[i]?.querySelector('.page-body');if(!body)return;body.querySelectorAll('h2,h3,p,li,figcaption,dt,dd').forEach(el=>{if(el.closest('button,nav,.folio,.quiz-feedback,.quiz-privacy,.status-chip,.passport'))return;const t=(el.innerText||el.textContent).replace(/\s+/g,' ').trim();if(t.length<2)return;(t.match(/[^.!?]+[.!?]*/g)||[t]).forEach(x=>{x=x.trim();if(x)lines.push(/[.!?]$/.test(x)?x:x+'.')})})});return lines}
