function drawRoute(i){const svg=$('#mapRoute'),pts=tourStops.map(stopPoint).map(p=>p.join(',')).join(' '),done=tourStops.slice(0,i+1).map(stopPoint).map(p=>p.join(',')).join(' ');svg.innerHTML=`<polyline class="route-all" points="${pts}"/><polyline class="route-done" points="${done}"/>`;svg.classList.toggle('on',i>=0)}
