// Cari: indeks teks seluruh halaman isi, hasil dengan cuplikan, lalu sorot kata di halaman tujuan.
const searchDialog=$('#searchDialog'),searchInput=$('#searchInput');
const fold=t=>t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const skipKinds=new Set(['cover','back','quiz','quiz-summary','references']),skipKeys=new Set(['image','imageSource','imageLicense','source','sourceName','videoId','icon','kind','number','populationSource']);
