const searchIndex=pages.map((p,i)=>{if(skipKinds.has(p.kind))return null;const parts=[];collectText(p,parts);const text=parts.join(' \u2022 ').replace(/\s+/g,' ');return{i,label:p.label||p.title||'',text,folded:fold(text)}}).filter(Boolean);
