/* Sesi 91: header HP hanya 2 tombol (Tentang & ekspor + Daftar isi); alat lain pindah ke laci */
(function(){function mk(){const act=document.querySelector('.header-actions'),oa=document.getElementById('openAbout'),oc=document.getElementById('openContents');if(!act||!oa||!oc||document.getElementById('aboutHeader'))return;const b=document.createElement('button');b.type='button';b.id='aboutHeader';b.className='header-icon';b.setAttribute('aria-label','Tentang buku dan ekspor');b.title='Tentang & ekspor';b.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3.5h9a6.5 6.5 0 0 1 6.5 6.5v9a1.5 1.5 0 0 1-1.5 1.5H5A1.5 1.5 0 0 1 3.5 19V5A1.5 1.5 0 0 1 5 3.5z"/><path d="M12 11.5v5M12 7.8h.01"/></svg>';b.onclick=()=>oa.click();act.insertBefore(b,oc)}
setInterval(mk,500)})();

/* Sesi 101: muat-otomatis teks. Font bawaan HP (Roboto/Noto) lebih lebar dari font uji, sehingga isi bisa menabrak
   nomor halaman/pil Menu-Lanjut. Bila isi melewati garis folio, ukuran huruf halaman itu diperkecil bertahap
   (paling banyak 28%) sampai muat. Halaman yang sudah muat tidak diubah. */
window.fitText=function(){
  const MIN=.72,STEP=.03;
  document.querySelectorAll('#book .book-page').forEach(p=>{
    const body=p.querySelector('.page-body'),fo=p.querySelector('.folio'),pc=p.querySelector('.page-content');
    if(!body||!fo||!pc||body.classList.contains('menu-page'))return;
    const R=pc.getBoundingClientRect();if(R.width<50||R.right<0||R.left>innerWidth)return;
    const els=[body,...body.querySelectorAll('*')].filter(e=>e.tagName!=='IMG'&&e.tagName!=='SVG'&&e.tagName!=='svg'&&!e.closest('svg'));
    els.forEach(e=>{if(e.dataset.fs0===undefined){const cs=getComputedStyle(e),lh=parseFloat(cs.lineHeight);e.dataset.fs0=parseFloat(cs.fontSize);e.dataset.lh0=isNaN(lh)?'':lh}});
    const apply=k=>els.forEach(e=>{const f=+e.dataset.fs0;if(!f)return;e.style.fontSize=(f*k).toFixed(2)+'px';if(e.dataset.lh0!=='')e.style.lineHeight=(+e.dataset.lh0*k).toFixed(2)+'px'});
    const sc=R.width/480;
    const over=()=>{const limit=fo.getBoundingClientRect().top-4;let m=0;body.querySelectorAll('*').forEach(e=>{if(e.closest('svg')||e.closest('.folio'))return;const cs=getComputedStyle(e);if(cs.display==='none'||cs.position==='absolute'||cs.position==='fixed')return;const r=e.getBoundingClientRect();if(r.height>0&&r.bottom>m)m=r.bottom});return (m-limit)/sc};
    apply(1);
    let k=1;
    while(over()>0&&k>MIN+.001){k=Math.max(MIN,+(k-STEP).toFixed(2));apply(k)}
    if(k===1)els.forEach(e=>{e.style.removeProperty('font-size');e.style.removeProperty('line-height')});
    p.dataset.fit=k;
  });
};
if(document.fonts&&document.fonts.ready)document.fonts.ready.then(()=>setTimeout(()=>window.fitText&&window.fitText(),300));
